{
  "items": [
    {
      "i": 0,
      "text": "The music library is great, but the app crashes on my phone every few days. It's annoying but I still use it."
    },
    {
      "i": 1,
      "text": "I like the playlists, but the price went up again. It's getting hard to justify compared to other services."
    },
    {
      "i": 2,
      "text": "Best music app ever. The recommendations are spot on and the family plan is a lifesaver for us."
    },
    {
      "i": 3,
      "text": "Good catalog, but the UI changes are confusing. I keep missing the shuffle button."
    },
    {
      "i": 4,
      "text": "Love the podcasts and music integration. The audio quality is solid for the price."
    },
    {
      "i": 5,
      "text": "Spotify is essential for my daily commute. The offline downloads work perfectly and the app is stable."
    },
    {
      "i": 6,
      "text": "Too many ads on the free tier. I tried to upgrade but the student discount is a hassle to renew."
    },
    {
      "i": 7,
      "text": "The app keeps disconnecting from my car's Bluetooth. Very frustrating when I'm driving."
    },
    {
      "i": 8,
      "text": "The new lyrics feature is amazing. I can't imagine listening to music without it now."
    },
    {
      "i": 9,
      "text": "Superb recommendation engine. It finds obscure tracks I actually like. Worth every penny."
    },
    {
      "i": 10,
      "text": "Decent service, but the customer support is non-existent. I've been waiting weeks for a refund."
    },
    {
      "i": 11,
      "text": "The shuffle mode is broken. It repeats the same songs over and over. Very disappointing."
    },
    {
      "i": 12,
      "text": "Great for discovering new artists. The interface is clean and easy to use."
    },
    {
      "i": 13,
      "text": "I use it for everything. Music, podcasts, audiobooks. It's my go-to app."
    },
    {
      "i": 14,
      "text": "The app is slow on my older phone. It takes forever to load playlists."
    },
    {
      "i": 15,
      "text": "The family plan is a steal. Everyone in the house loves their personalized recommendations."
    },
    {
      "i": 16,
      "text": "Best in class. The audio quality is crisp and the catalog is unmatched."
    },
    {
      "i": 17,
      "text": "Good service, but I wish the offline downloads were more reliable. They often disappear."
    },
    {
      "i": 18,
      "text": "I like the music, but the app is a bit bloated. It uses too much battery."
    },
    {
      "i": 19,
      "text": "Terrible. The app crashed during a live stream and I lost my session. No support."
    },
    {
      "i": 20,
      "text": "Worst experience ever. My account was banned for no reason and I can't get it back."
    },
    {
      "i": 21,
      "text": "Love the new features. The app is fast and the music selection is huge."
    },
    {
      "i": 22,
      "text": "It's okay, but I miss the old interface. The new design is too cluttered."
    },
    {
      "i": 23,
      "text": "Great for work. The focus playlists are really helpful for productivity."
    },
    {
      "i": 24,
      "text": "The price is too high for what you get. I'm considering switching to Apple Music."
    }
  ]
}
